<template>
  <div>
    <h2 class="catagoryHeader">Communication & Interaction</h2>
    <AntipatternInfoComponent :antiPatternsAll="antiPatterns"/>
  </div>
</template>

<script setup lang="ts">
import {ref} from "vue";
import {listUsingGetByCategoryName} from "../../api/msdv-backend";
import AntipatternInfoComponent from "@/components/AntipatternInfoComponent.vue";

// region 从数据库获取按分类筛选后的微服务异味信息
const antiPatterns = ref<API.AntipatternInfoVO[]>([]);
const getAntiPatternsInfo = async () => {
  let res = await listUsingGetByCategoryName("Communication & Interaction");

  res.data?.forEach((antipatternInfoVO: API.AntipatternInfoVO) => {
    antiPatterns.value.push(antipatternInfoVO);
  })
  // console.log(antiPatterns);
}

getAntiPatternsInfo();
//endregion

</script>

